-- Connect VibeSchool-authored Grade 1 Creative Activities curriculum to the existing
-- teacher-owned Scheme of Work via persistent sub-strand and outcome IDs.
-- This is NOT a reproduction of official KICD wording or KICD verification.
begin;

create unique index if not exists cbc_grade1_creative_source_unique
  on public.cbc_strands (source_ref)
  where source_ref like 'VS-CUR-G01-CA-2026#%';

create unique index if not exists curriculum_grade1_creative_outcome_source_unique
  on public.curriculum_learning_outcomes (source_ref)
  where source_ref like 'VS-CUR-G01-CA-2026#%';

-- authorization-test: public.curriculum_unit_guidance
-- Assert anon has no SELECT, only authenticated readers can see active VibeSchool
-- Grade 1 sourced guidance, and school teachers cannot write global guidance.
create table if not exists public.curriculum_unit_guidance (
  sub_strand_id uuid primary key references public.cbc_strands(id) on delete cascade,
  suggested_lessons integer not null check (suggested_lessons > 0),
  learning_resources text not null,
  assessment_methods text not null,
  competencies text,
  safety_notes text,
  content_status text not null default 'draft' check (content_status in ('draft','active','archived')),
  updated_at timestamptz not null default now()
);
alter table public.curriculum_unit_guidance enable row level security;
revoke all on public.curriculum_unit_guidance from anon;
grant select on public.curriculum_unit_guidance to authenticated;
drop policy if exists grade1_creative_guidance_read on public.curriculum_unit_guidance;
create policy grade1_creative_guidance_read on public.curriculum_unit_guidance for select to authenticated
using (content_status='active' and exists (
  select 1 from public.cbc_strands s where s.id=sub_strand_id
    and s.source_ref like 'VS-CUR-G01-CA-2026#%'
));

-- authorization-test: public.scheme_lesson_outcomes
-- Assert anon cannot read/write links; an authenticated teacher can only link
-- outcomes to a scheme lesson owned by that teacher and assigned class/subject.
create table if not exists public.scheme_lesson_outcomes (
  scheme_lesson_id uuid not null references public.scheme_of_work(id) on delete cascade,
  curriculum_outcome_id uuid not null references public.curriculum_learning_outcomes(id) on delete restrict,
  created_at timestamptz not null default now(),
  primary key (scheme_lesson_id,curriculum_outcome_id)
);
create index if not exists scheme_lesson_outcomes_curriculum_outcome_idx
  on public.scheme_lesson_outcomes (curriculum_outcome_id);
alter table public.scheme_lesson_outcomes enable row level security;
revoke all on public.scheme_lesson_outcomes from anon;
grant select, insert, delete on public.scheme_lesson_outcomes to authenticated;
drop policy if exists scheme_lesson_outcomes_read on public.scheme_lesson_outcomes;
create policy scheme_lesson_outcomes_read on public.scheme_lesson_outcomes for select to authenticated
using (exists (select 1 from public.scheme_of_work sw where sw.id=scheme_lesson_id));
drop policy if exists scheme_lesson_outcomes_teacher_insert on public.scheme_lesson_outcomes;
create policy scheme_lesson_outcomes_teacher_insert on public.scheme_lesson_outcomes for insert to authenticated
with check (exists (
  select 1 from public.scheme_of_work sw
  where sw.id=scheme_lesson_id and sw.teacher_id=(select auth.uid())
    and exists (select 1 from public.teacher_classes tc
      where tc.teacher_id=(select auth.uid()) and tc.school_id=sw.school_id
        and tc.class_id=sw.class_id and tc.subject_id=sw.subject_id)
));
drop policy if exists scheme_lesson_outcomes_teacher_delete on public.scheme_lesson_outcomes;
create policy scheme_lesson_outcomes_teacher_delete on public.scheme_lesson_outcomes for delete to authenticated
using (exists (select 1 from public.scheme_of_work sw where sw.id=scheme_lesson_id and sw.teacher_id=(select auth.uid())));

drop policy if exists grade1_creative_authored_outcomes_read on public.curriculum_learning_outcomes;
create policy grade1_creative_authored_outcomes_read on public.curriculum_learning_outcomes
  for select to authenticated using (
    status='active' and source_type='creator_claimed' and created_by is null
    and source_ref like 'VS-CUR-G01-CA-2026#%'
  );

-- The seed follows the VibeSchool-authored native reader; it remains independently
-- written, unverified KICD-aligned material and must not be labelled official.
with v as (select $vs_g1$[{"id":"1.1","title":"Jumping","strand":1,"lessons":14,"outcomes":["Recognise different kinds of jumps and how each challenges body control.","Plan and make simple, safe jump markers from appropriate materials.","Perform small jumps for height and distance, including changes of direction.","Coordinate jumping movements with group singing.","Take part confidently while observing personal and shared safety."],"experiences":["Compare demonstrations of upward, forward and sideways jumping and describe how the body moves.","Set out flat markers, agree on safe landing areas and practise height, distance and directional jumps.","Coordinate jumps with a simple song, then discuss safe landings and helpful techniques."],"inquiry":["How does the direction of a jump change our movement?","What makes homemade jumping markers safe?"],"resources":"Level open space, flat markers, pictures, soft mats where available and drinking water.","assessment":"Observe jump types, controlled take-off and landing, directions, safe improvisation, coordination with a song and positive participation.","competencies":"Creativity; communication and collaboration; responsibility and unity.","safety":"Avoid raised obstacles, slippery surfaces and overcrowding. Offer an accessible low-impact movement alternative."},{"id":"1.2","title":"Rhythm","strand":1,"lessons":14,"outcomes":["Recognise regular pulses in everyday sounds.","Keep a steady beat using a percussion instrument while singing.","Create a body-percussion accompaniment for a familiar song.","Appreciate rhythmic sound-making with others."],"experiences":["Listen for repeating pulses and mark them by clapping, tapping, marching or stamping.","Use a safe shaker or drum to maintain a beat while a group sings.","Invent a short body-sound pattern, repeat it and reflect on the group timing."],"inquiry":["How does a regular beat help a group sing together?","How can hands and feet become percussion instruments?"],"resources":"Hands, safe shakers or drums, familiar songs and optional sound recordings.","assessment":"Listen for recognition of pulse, steady timing, a repeatable original pattern and respectful group performance.","competencies":"Learning to learn; self-efficacy; teamwork; unity.","safety":null},{"id":"1.3","title":"Drawing","strand":1,"lessons":14,"outcomes":["Identify straight, curved, wavy and zigzag lines.","Draw vertical, horizontal and diagonal lines.","Combine different line types to make repeated patterns.","Use drawing to express ideas and appreciate the work of others."],"experiences":["Find line types in familiar objects and pictures.","Draw lines in varied directions using pencils, crayons or suitable local tools.","Arrange different lines into a repeating pattern and share what the image communicates."],"inquiry":["What can we express by changing the direction or shape of a line?"],"resources":"Paper, pencils, crayons or safe charcoal, example images and reusable drawing surfaces.","assessment":"Inspect line identification, direction, pattern repetition, personal expression and constructive response to artwork.","competencies":"Creativity and imagination; communication; care for shared materials.","safety":null},{"id":"1.4","title":"Stretching","strand":1,"lessons":14,"outcomes":["Identify body parts used during stretching.","Demonstrate gentle stretches forwards, backwards, sideways and upwards in different positions.","Participate willingly in stretching for physical fitness."],"experiences":["Name joints and limbs used in stretching.","Demonstrate gentle stretches while standing, sitting, kneeling or lying with safe body control.","Try an age-appropriate flexibility game and discuss how stretching feels."],"inquiry":["Why do we stretch in different directions and positions?"],"resources":"Clean mats, direction cards, a safe open area and chairs for adapted movement.","assessment":"Observe body-part awareness, correct directions, controlled movement, safety and willingness to participate.","competencies":"Collaboration; self-awareness; personal responsibility and care.","safety":"Do not force joints or stretch to pain. Provide seated or supported alternatives."},{"id":"1.5","title":"Painting and Colouring","strand":1,"lessons":14,"outcomes":["Identify suitable painting and colouring tools.","Choose colours to represent observed surroundings.","Apply paint inside simple shapes using a brush.","Make expressive marks or images with finger painting.","Use a sponge to apply paint to a surface.","Enjoy expressing ideas through colour and paint."],"experiences":["Explore objects, scenes, colours and appropriate tools.","Practise colouring within simple shapes and use brushes, fingers and sponges to make different marks.","Display work, explain material choices and clean the workspace responsibly."],"inquiry":["What changes when we paint using a brush, fingers or a sponge?"],"resources":"Non-toxic paint, broad brushes, clean sponges, paper, water and protective clothing.","assessment":"Check tool recognition, colour choice, brush/finger/sponge techniques, finished work and safe clean-up.","competencies":"Critical thinking; creativity; self-efficacy; responsibility.","safety":"Use washable non-toxic materials; prevent ingestion and provide alternatives for skin sensitivity."},{"id":"1.6","title":"Melody","strand":1,"lessons":14,"outcomes":["Distinguish melodic sounds from ordinary noise.","Compare short melodic phrases for similarity or difference.","Repeat short tunes by humming or singing.","Enjoy careful listening and musical echoing."],"experiences":["Listen to pitched and non-pitched sounds and compare them.","Listen to pairs of short melodies and identify which sound alike.","Echo brief tunes with the voice, individually or in a supportive group."],"inquiry":["How can careful listening tell us whether two tunes are alike?"],"resources":"Teacher voice, short tune examples and optional tuned instruments or recordings.","assessment":"Use listening checks and short echo activities to assess pitch awareness, phrase matching and participation.","competencies":"Listening; self-efficacy; communication and collaboration.","safety":null},{"id":"1.7","title":"Pattern Making","strand":1,"lessons":10,"outcomes":["Recognise repeating arrangements made with letters and numbers.","Create patterns using repeating letters.","Make number-based visual patterns.","Enjoy using repetition for creative expression."],"experiences":["Observe and describe repeated letters and numerals.","Arrange letter cards in a predictable pattern and explain the repeating section.","Create and share an original number-based pattern."],"inquiry":["How can we tell what comes next in a repeating pattern?"],"resources":"Letter and number cards, pencils, paper, string and reusable tiles.","assessment":"Look for correct identification of the repeating part, ability to extend and create patterns, and an explanation of the pattern rule.","competencies":"Creativity; learning to learn; communication; responsibility.","safety":null},{"id":"2.1","title":"Kenyan Singing Games","strand":2,"lessons":13,"outcomes":["Identify props used in singing games from Kenyan communities.","Make an appropriate simple substitute prop.","Participate in a culturally grounded singing game with music, movement and roles.","Appreciate singing-game traditions and respectful group participation."],"experiences":["Observe examples of local singing games and name their props.","Make a safe prop using available materials and practise group roles and formations.","Perform a selected game and discuss its cultural meaning and group cooperation."],"inquiry":["How do props and group roles enrich a singing game?"],"resources":"Age-appropriate local songs, safe recycled props, a suitable movement area and community examples.","assessment":"Observe props, safe improvisation, song participation, formations, teamwork and respect for cultural practices.","competencies":"Citizenship; confidence; cooperation; cultural respect.","safety":"Avoid unsafe props and stereotypes; adapt roles so all learners can participate."},{"id":"2.2","title":"Throwing and Catching","strand":2,"lessons":14,"outcomes":["Identify safe reusable materials for making a soft ball.","Make a suitable ball from available materials.","Throw and catch a ball with increasing control.","Enjoy cooperating in ball games."],"experiences":["Sort clean, safe and unsafe ball-making materials.","Make a soft lightweight ball using fabric or paper with appropriate guidance.","Practise short-distance throws, catches and simple cooperative games."],"inquiry":["What helps another player catch a ball successfully?"],"resources":"Soft balls, clean reusable fabric or paper, tape, targets and a clear open area.","assessment":"Check material choice, ball construction, controlled throw and catch, safe spacing and cooperation.","competencies":"Self-efficacy; collaboration; environmental care.","safety":"Use soft balls, leave sufficient space and adapt ball size or distance to learner needs."},{"id":"2.3","title":"Paper Craft","strand":2,"lessons":10,"outcomes":["Identify objects made from paper.","Make an object by pleating paper.","Create an object through paper folding.","Use completed paper objects imaginatively in play."],"experiences":["Observe everyday items made from paper and select clean materials.","Make a simple pleated paper fan and a different folded shape.","Use the completed items in imaginative play and describe the methods used."],"inquiry":["How does folding change what a piece of paper can become?"],"resources":"Clean reused paper, example fans or toys, picture instructions and blunt tools.","assessment":"Look for recognition of paper-made objects, purposeful pleating, correct folding and imaginative use.","competencies":"Creativity; communication; learning to learn; responsible reuse.","safety":"Avoid staples and sharp blades. Offer large sheets and tactile support where needed."},{"id":"2.4","title":"Log Roll and T-Balance","strand":2,"lessons":14,"outcomes":["Recognise body actions used in log rolling and T-balancing.","Prepare a safe movement area with simple markers.","Perform a controlled log roll.","Hold an appropriately aligned T-balance.","Participate positively while observing movement safety."],"experiences":["Observe safe demonstrations of log rolling and a T-shaped balance.","Prepare a clear marked area and practise gradual balance movements with supervision.","Demonstrate an appropriate roll or adapted movement and reflect on body control."],"inquiry":["Why are body control and space important during rolling and balancing?"],"resources":"Soft gym mats, floor markers, level space and trained adult supervision.","assessment":"Observe understanding, safe space preparation, body alignment, controlled movement and responsibility.","competencies":"Problem solving; cooperation; personal safety and respect.","safety":"No rolls on hard ground or near obstacles; supervise closely and offer adapted alternatives."},{"id":"2.5","title":"Action Songs","strand":2,"lessons":13,"outcomes":["Explain the main idea communicated by an appropriate action song.","Perform action songs with suitable tune, rhythm, words, gestures and expression.","Enjoy expressive group singing and value others’ participation."],"experiences":["Listen to a suitable song and discuss its message.","Practise matching gestures to words and maintaining a steady group rhythm.","Perform together and offer constructive comments about clarity and expression."],"inquiry":["How can movement help communicate the meaning of a song?"],"resources":"Age-appropriate songs, gesture cards, optional recordings and safe space.","assessment":"Assess song-message understanding, coordinated movements, tune, rhythm, clear words and cooperative singing.","competencies":"Communication and collaboration; creativity; confidence.","safety":null},{"id":"2.6","title":"Modelling: Pinch Method","strand":2,"lessons":14,"outcomes":["Identify simple objects shaped using the pinch technique.","Choose appropriate modelling materials and tools.","Create an object using controlled thumb-and-finger pinching.","Appreciate modelling and share completed objects confidently."],"experiences":["Observe examples of vessels or objects made from soft modelling media.","Press and pinch clay or dough to form a simple hollow or raised shape.","Display models, describe the technique and clean up or reuse materials."],"inquiry":["How can our fingers shape soft material into a useful object?"],"resources":"Clean non-toxic clay or dough, mats, sample objects and washing water.","assessment":"Look for appropriate material choice, recognisable pinch technique, completed form and explanation.","competencies":"Problem solving; creativity; self-efficacy; sustainability.","safety":"Use non-toxic material and supervise small tools or loose parts."},{"id":"2.7","title":"Percussion Musical Instruments","strand":2,"lessons":10,"outcomes":["Recognise percussion instruments from several Kenyan communities.","Make a simple playable percussion instrument from suitable materials.","Play a percussion instrument for enjoyment or to support a song.","Appreciate the place of percussion in Kenyan cultural life."],"experiences":["Observe drums, shakers or jingles and discuss their sound sources.","Construct a safe shaker or similar instrument using available clean materials.","Practise striking or shaking in time with singing and reflect on cultural uses."],"inquiry":["How can safe everyday materials become musical instruments?"],"resources":"Illustrations of Kenyan percussion, sealed containers, safe filling materials and suitable tape.","assessment":"Check instrument recognition, safe construction, playable sound, rhythmic accompaniment and cultural respect.","competencies":"Creativity; citizenship; teamwork; environmental responsibility.","safety":"Secure small fillings, supervise construction and protect hearing."},{"id":"3.1","title":"Musical Sounds","strand":3,"lessons":14,"outcomes":["Identify sound sources involving people, animals, birds and ordinary objects.","Distinguish loud/soft, fast/slow and high/low qualities in sounds.","Express personal responses to environmental sounds.","Describe the mood evoked by a short musical passage.","Enjoy listening carefully and talking about music."],"experiences":["Listen to and identify sounds from familiar environments.","Compare paired examples for volume, speed and pitch.","Respond to short music or sounds with appropriate words, drawings or movement and describe the mood."],"inquiry":["How do we identify sound qualities and what they make us feel?"],"resources":"Voices, nearby sounds, picture cards and optional short sound recordings.","assessment":"Check sound-source recognition, comparison of qualities, mood responses and respectful listening.","competencies":"Communication; creative imagination; cultural sensitivity.","safety":"Avoid excessive sound levels; offer visual or vibration cues for varied hearing needs."},{"id":"3.2","title":"Water Safety Awareness","strand":3,"lessons":14,"outcomes":["Identify common water collection and storage points near home.","Recognise dangers associated with household and community water locations.","Make a picture montage showing water points.","Describe safe behaviour near different water sources.","Value water safety as an everyday life-protection habit."],"experiences":["Examine pictures of tanks, containers, wells, rivers and other local water points.","Discuss realistic dangers and identify safer behaviour and when to seek adult help.","Create a picture montage showing water sources, warning signs and safety actions."],"inquiry":["How can we recognise and avoid danger around water?"],"resources":"Pictures of water points, paper, glue, warning-sign images and adult-approved rules.","assessment":"Check recognition of water points and hazards, montage accuracy, safe-action descriptions and responsible behaviour.","competencies":"Communication; personal responsibility; health and safety awareness.","safety":"Use classroom pictures and discussions; never take young learners to unsafe water sites for this activity."}]$vs_g1$::jsonb as units),
subject as (
  select id from public.subjects where name='Creative Arts and Sports'
    and school_id is null and global_subject_id is null
),
catalog as (
  select elem as unit from v cross join lateral jsonb_array_elements(v.units) elem
)
insert into public.cbc_strands
  (subject_id,grade,name,sub_strand,strand_order,sub_strand_order,
   key_inquiry_questions,suggested_experiences,source_ref)
select subject.id,'Grade 1',
  case (catalog.unit->>'strand')::integer
    when 1 then 'Creating and Executing'
    when 2 then 'Performing and Displaying'
    when 3 then 'Appreciation' end,
  catalog.unit->>'title',
  (catalog.unit->>'strand')::integer,
  split_part(catalog.unit->>'id','.',2)::integer,
  array(select jsonb_array_elements_text(catalog.unit->'inquiry')),
  array(select jsonb_array_elements_text(catalog.unit->'experiences')),
  'VS-CUR-G01-CA-2026#'||(catalog.unit->>'id')
from catalog cross join subject
on conflict (subject_id,grade,name,sub_strand) do nothing;

