d","strand":2,"lessons":14,"outcomes":["Identify simple objects shaped using the pinch technique.","Choose appropriate modelling materials and tools.","Create an object using controlled thumb-and-finger pinching.","Appreciate modelling and share completed objects confidently."],"experiences":["Observe examples of vessels or objects made from soft modelling media.","Press and pinch clay or dough to form a simple hollow or raised shape.","Display models, describe the technique and clean up or reuse materials."],"inquiry":["How can our fingers shape soft material into a useful object?"],"resources":"Clean non-toxic clay or dough, mats, sample objects and washing water.","assessment":"Look for appropriate material choice, recognisable pinch technique, completed form and explanation.","competencies":"Problem solving; creativity; self-efficacy; sustainability.","safety":"Use non-toxic material and supervise small tools or loose parts."},{"id":"2.7","title":"Percussion Musical Instruments","strand":2,"lessons":10,"outcomes":["Recognise percussion instruments from several Kenyan communities.","Make a simple playable percussion instrument from suitable materials.","Play a percussion instrument for enjoyment or to support a song.","Appreciate the place of percussion in Kenyan cultural life."],"experiences":["Observe drums, shakers or jingles and discuss their sound sources.","Construct a safe shaker or similar instrument using available clean materials.","Practise striking or shaking in time with singing and reflect on cultural uses."],"inquiry":["How can safe everyday materials become musical instruments?"],"resources":"Illustrations of Kenyan percussion, sealed containers, safe filling materials and suitable tape.","assessment":"Check instrument recognition, safe construction, playable sound, rhythmic accompaniment and cultural respect.","competencies":"Creativity; citizenship; teamwork; environmental responsibility.","safety":"Secure small fillings, supervise construction and protect hearing."},{"id":"3.1","title":"Musical Sounds","strand":3,"lessons":14,"outcomes":["Identify sound sources involving people, animals, birds and ordinary objects.","Distinguish loud/soft, fast/slow and high/low qualities in sounds.","Express personal responses to environmental sounds.","Describe the mood evoked by a short musical passage.","Enjoy listening carefully and talking about music."],"experiences":["Listen to and identify sounds from familiar environments.","Compare paired examples for volume, speed and pitch.","Respond to short music or sounds with appropriate words, drawings or movement and describe the mood."],"inquiry":["How do we identify sound qualities and what they make us feel?"],"resources":"Voices, nearby sounds, picture cards and optional short sound recordings.","assessment":"Check sound-source recognition, comparison of qualities, mood responses and respectful listening.","competencies":"Communication; creative imagination; cultural sensitivity.","safety":"Avoid excessive sound levels; offer visual or vibration cues for varied hearing needs."},{"id":"3.2","title":"Water Safety Awareness","strand":3,"lessons":14,"outcomes":["Identify common water collection and storage points near home.","Recognise dangers associated with household and community water locations.","Make a picture montage showing water points.","Describe safe behaviour near different water sources.","Value water safety as an everyday life-protection habit."],"experiences":["Examine pictures of tanks, containers, wells, rivers and other local water points.","Discuss realistic dangers and identify safer behaviour and when to seek adult help.","Create a picture montage showing water sources, warning signs and safety actions."],"inquiry":["How can we recognise and avoid danger around water?"],"resources":"Pictures of water points, paper, glue, warning-sign images and adult-approved rules.","assessment":"Check recognition of water points and hazards, montage accuracy, safe-action descriptions and responsible behaviour.","competencies":"Communication; personal responsibility; health and safety awareness.","safety":"Use classroom pictures and discussions; never take young learners to unsafe water sites for this activity."}]$vs_g1$::jsonb as units),
catalog as (select elem as unit from v cross join lateral jsonb_array_elements(v.units) elem)
insert into public.curriculum_unit_guidance
  (sub_strand_id,suggested_lessons,learning_resources,assessment_methods,competencies,safety_notes,content_status)
select s.id,(catalog.unit->>'lessons')::integer,
  catalog.unit->>'resources',catalog.unit->>'assessment',
  catalog.unit->>'competencies',catalog.unit->>'safety','active'
from catalog
join public.cbc_strands s on s.source_ref='VS-CUR-G01-CA-2026#'||(catalog.unit->>'id')
on conflict (sub_strand_id) do nothing;

with v as (select $vs_g1$[{"id":"1.1","title":"Jumping","strand":1,"lessons":14,"outcomes":["Recognise different kinds of jumps and how each challenges body control.","Plan and make simple, safe jump markers from appropriate materials.","Perform small jumps for height and distance, including changes of direction.","Coordinate jumping movements with group singing.","Take part confidently while observing personal and shared safety."],"experiences":["Compare demonstrations of upward, forward and sideways jumping and describe how the body moves.","Set out flat markers, agree on safe landing areas and practise height, distance and directional jumps.","Coordinate jumps with a simple song, then discuss safe landings and helpful techniques."],"inquiry":["How does the direction of a jump change our movement?","What makes homemade jumping markers safe?"],"resources":"Level open space, flat markers, pictures, soft mats where available and drinking water.","assessment":"Observe jump types, controlled take-off and landing, directions, safe improvisation, coordination with a song and positive participation.","competencies":"Creativity; communication and collaboration; responsibility and unity.","safety":"Avoid raised obstacles, slippery surfaces and overcrowding. Offer an accessible low-impact movement alternative."},{"id":"1.2","title":"Rhythm","strand":1,"lessons":14,"outcomes":["Recognise regular pulses in everyday sounds.","Keep a steady beat using a percussion instrument while singing.","Create a body-percussion accompaniment for a familiar song.","Appreciate rhythmic sound-making with others."],"experiences":["Listen for repeating pulses and mark them by clapping, tapping, marching or stamping.","Use a safe shaker or drum to maintain a beat while a group sings.","Invent a short body-sound pattern, repeat it and reflect on the group timing."],"inquiry":["How does a regular beat help a group sing together?","How can hands and feet become percussion instruments?"],"resources":"Hands, safe shakers or drums, familiar songs and optional sound recordings.","assessment":"Listen for recognition of pulse, steady timing, a repeatable original pattern and respectful group performance.","competencies":"Learning to learn; self-efficacy; teamwork; unity.","safety":null},{"id":"1.3","title":"Drawing","strand":1,"lessons":14,"outcomes":["Identify straight, curved, wavy and zigzag lines.","Draw vertical, horizontal and diagonal lines.","Combine different line types to make repeated patterns.","Use drawing to express ideas and appreciate the work of others."],"experiences":["Find line types in familiar objects and pictures.","Draw lines in varied directions using pencils, crayons or suitable local tools.","Arrange different lines into a repeating pattern and share what the image communicates."],"inquiry":["What can we express by changing the direction or shape of a line?"],"resources":"Paper, pencils, crayons or safe charcoal, example images and reusable drawing surfaces.","assessment":"Inspect line identification, direction, pattern repetition, personal expression and constructive response to artwork.","competencies":"Creativity and imagination; communication; care for shared materials.","safety":null},{"id":"1.4","title":"Stretching","strand":1,"lessons":14,"outcomes":["Identify body parts used during stretching.","Demonstrate gentle stretches forwards, backwards, sideways and upwards in different positions.","Participate willingly in stretching for physical fitness."],"experiences":["Name joints and limbs used in stretching.","Demonstrate gentle stretches while standing, sitting, kneeling or lying with safe body control.","Try an age-appropriate flexibility game and discuss how stretching feels."],"inquiry":["Why do we stretch in different directions and positions?"],"resources":"Clean mats, direction cards, a safe open area and chairs for adapted movement.","assessment":"Observe body-part awareness, correct directions, controlled movement, safety and willingness to participate.","competencies":"Collaboration; self-awareness; personal responsibility and care.","safety":"Do not force joints or stretch to pain. Provide seated or supported alternatives."},{"id":"1.5","title":"Painting and Colouring","strand":1,"lessons":14,"outcomes":["Identify suitable painting and colouring tools.","Choose colours to represent observed surroundings.","Apply paint inside simple shapes using a brush.","Make expressive marks or images with finger painting.","Use a sponge to apply paint to a surface.","Enjoy expressing ideas through colour and paint."],"experiences":["Explore objects, scenes, colours and appropriate tools.","Practise colouring within simple shapes and use brushes, fingers and sponges to make different marks.","Display work, explain material choices and clean the workspace responsibly."],"inquiry":["What changes when we paint using a brush, fingers or a sponge?"],"resources":"Non-toxic paint, broad brushes, clean sponges, paper, water and protective clothing.","assessment":"Check tool recognition, colour choice, brush/finger/sponge techniques, finished work and safe clean-up.","competencies":"Critical thinking; creativity; self-efficacy; responsibility.","safety":"Use washable non-toxic materials; prevent ingestion and provide alternatives for skin sensitivity."},{"id":"1.6","title":"Melody","strand":1,"lessons":14,"outcomes":["Distinguish melodic sounds from ordinary noise.","Compare short melodic phrases for similarity or difference.","Repeat short tunes by humming or singing.","Enjoy careful listening and musical echoing."],"experiences":["Listen to pitched and non-pitched sounds and compare them.","Listen to pairs of short melodies and identify which sound alike.","Echo brief tunes with the voice, individually or in a supportive group."],"inquiry":["How can careful listening tell us whether two tunes are alike?"],"resources":"Teacher voice, short tune examples and optional tuned instruments or recordings.","assessment":"Use listening checks and short echo activities to assess pitch awareness, phrase matching and participation.","competencies":"Listening; self-efficacy; communication and collaboration.","safety":null},{"id":"1.7","title":"Pattern Making","strand":1,"lessons":10,"outcomes":["Recognise repeating arrangements made with letters and numbers.","Create patterns using repeating letters.","Make number-based visual patterns.","Enjoy using repetition for creative expression."],"experiences":["Observe and describe repeated letters and numerals.","Arrange letter cards in a predictable pattern and explain the repeating section.","Create and share an original number-based pattern."],"inquiry":["How can we tell what comes next in a repeating pattern?"],"resources":"Letter and number cards, pencils, paper, string and reusable tiles.","assessment":"Look for correct identification of the repeating part, ability to extend and create patterns, and an explanation of the pattern rule.","competencies":"Creativity; learning to learn; communication; responsibility.","safety":null},{"id":"2.1","title":"Kenyan Singing Games","strand":2,"lessons":13,"outcomes":["Identify props used in singing games from Kenyan communities.","Make an appropriate simple substitute prop.","Participate in a culturally grounded singing game with music, movement and roles.","Appreciate singing-game traditions and respectful group participation."],"experiences":["Observe examples of local singing games and name their props.","Make a safe prop using available materials and practise group roles and formations.","Perform a selected game and discuss its cultural meaning and group cooperation."],"inquiry":["How do props and group roles enrich a singing game?"],"resources":"Age-appropriate local songs, safe recycled props, a suitable movement area and community examples.","assessment":"Observe props, safe improvisation, song participation, formations, teamwork and respect for cultural practices.","competencies":"Citizenship; confidence; cooperation; cultural respect.","safety":"Avoid unsafe props and stereotypes; adapt roles so all learners can participate."},{"id":"2.2","title":"Throwing and Catching","strand":2,"lessons":14,"outcomes":["Identify safe reusable materials for making a soft ball.","Make a suitable ball from available materials.","Throw and catch a ball with increasing control.","Enjoy cooperating in ball games."],"experiences":["Sort clean, safe and unsafe ball-making materials.","Make a soft lightweight ball using fabric or paper with appropriate guidance.","Practise short-distance throws, catches and simple cooperative games."],"inquiry":["What helps another player catch a ball successfully?"],"resources":"Soft balls, clean reusable fabric or paper, tape, targets and a clear open area.","assessment":"Check material choice, ball construction, controlled throw and catch, safe spacing and cooperation.","competencies":"Self-efficacy; collaboration; environmental care.","safety":"Use soft balls, leave sufficient space and adapt ball size or distance to learner needs."},{"id":"2.3","title":"Paper Craft","strand":2,"lessons":10,"outcomes":["Identify objects made from paper.","Make an object by pleating paper.","Create an object through paper folding.","Use completed paper objects imaginatively in play."],"experiences":["Observe everyday items made from paper and select clean materials.","Make a simple pleated paper fan and a different folded shape.","Use the completed items in imaginative play and describe the methods used."],"inquiry":["How does folding change what a piece of paper can become?"],"resources":"Clean reused paper, example fans or toys, picture instructions and blunt tools.","assessment":"Look for recognition of paper-made objects, purposeful pleating, correct folding and imaginative use.","competencies":"Creativity; communication; learning to learn; responsible reuse.","safety":"Avoid staples and sharp blades. Offer large sheets and tactile support whe